function model(p) {
  // Illustrative working session with an AI assistant. Sizes are made up but deterministic (seeded),
  // compaction is simplified: many assistants summarise older turns when the context nears its limit.
  const LIMIT = 200000, THRESH = 0.9 * LIMIT, SYS = 12000, KEEP = 2, FRAC = 0.12;
  const N = Math.max(5, Math.min(40, Math.round(p.turns)));
  const large = Math.round(p.toolSize) === 1, notes = Math.round(p.notes) === 1;
  let s = 20261003;
  const rnd = () => { s |= 0; s = s + 0x6D2B79F5 | 0; let t = Math.imul(s ^ s >>> 15, 1 | s); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; };
  const r100 = x => Math.round(x / 100) * 100;
  const ALL = [];
  for (let i = 1; i <= 40; i++) {
    const user = r100(500 + rnd() * 1700), reply = r100(1500 + rnd() * 3500);
    const small = r100(1200 + rnd() * 3600), big = r100(9000 + rnd() * 15000);
    ALL.push({ turn: i, user, reply, tool: large ? big : small });
  }
  // level 2 = headline (a gist survives every summary), 1 = gist survives one summary, 0 = detail (lost when summarised)
  const FACTS = [
    { id: 'org', turn: 1, from: 'you', text: 'Use the staging org, never production', gist: 'Work in a test org', level: 2 },
    { id: 'reports', turn: 3, from: 'you', text: 'Client wants weekly reports, sent Mondays', gist: 'Client wants regular reports', level: 2 },
    { id: 'budget', turn: 5, from: 'file', text: 'Budget cap: $40k (from SOW.pdf)', gist: 'There is a budget cap', level: 1 },
    { id: 'golive', turn: 8, from: 'you', text: 'Go-live date: 14 March', gist: null, level: 0 },
    { id: 'label', turn: 11, from: 'file', text: 'Keep the field label "Account Name"', gist: null, level: 0 },
    { id: 'approver', turn: 15, from: 'you', text: 'Priya approves every schema change', gist: 'Schema changes need approval', level: 1 },
    { id: 'optout', turn: 19, from: 'file', text: 'Never email "Do not contact" records', gist: 'Respect contact opt-outs', level: 2 },
    { id: 'region', turn: 25, from: 'you', text: 'Dashboard needs a region filter', gist: null, level: 0 }
  ];
  const factAt = t => { const f = FACTS.find(x => x.turn === t); return f ? f.id : null; };
  const sum = a => a.reduce((x, b) => x + b.total, 0);
  let live = [], summary = 0, gists = {}, notesBlock = 0, saved = [];
  const compactions = [], records = [], snaps = [], series = [], events = [];
  const usedNow = () => SYS + summary + notesBlock + sum(live);
  const status = () => FACTS.map(f => {
    if (f.turn > (live.length ? live[live.length - 1].turn : 0) && !gists[f.id]) return 'unsaid';
    if (saved.includes(f.id)) return 'notes';
    if (live.some(b => b.fact === f.id)) return 'verbatim';
    return gists[f.id] !== undefined ? 'gist' : 'lost';
  });
  const snap = () => ({ sys: SYS, summary, notes: notesBlock, live: live.map(b => b.turn), used: usedNow(), saved: saved.length, facts: status() });
  for (let t = 1; t <= N; t++) {
    const d = ALL[t - 1], b = { turn: t, user: d.user, tool: d.tool, reply: d.reply, total: d.user + d.tool + d.reply, fact: factAt(t) };
    const before = usedNow(), compacted = before + b.total > THRESH;
    if (compacted) {
      const fold = live.slice(0, -KEEP), keep = live.slice(-KEEP);
      const foldedTurns = sum(fold), oldSummary = summary, oldNotes = notesBlock, folded = foldedTurns + oldSummary;
      const ng = {};
      for (const id in gists) if (gists[id] === Infinity) ng[id] = Infinity; // a gist of a gist only keeps headlines
      fold.forEach(x => { const f = FACTS.find(y => y.id === x.fact); if (f && f.level > 0) ng[f.id] = f.level === 2 ? Infinity : 0; });
      gists = ng; summary = Math.round(FRAC * folded); live = keep;
      notesBlock = notes && saved.length ? 300 + 150 * saved.length : 0; // plan.md is re-read after compacting
      const after = usedNow();
      compactions.push({ n: compactions.length + 1, turn: t, before, foldedFrom: fold[0].turn, foldedTo: fold[fold.length - 1].turn, foldedTurns, oldSummary, oldNotes, summary, notesBlock, after, kept: keep.map(x => x.turn) });
      events.push({ type: 'compact', turn: t, units: 4 });
      snaps.push(snap());
    }
    live.push(b);
    if (notes && b.fact) saved.push(b.fact);
    records.push({ turn: t, before, size: b.total, compacted, after: usedNow() });
    events.push({ type: 'turn', turn: t, units: 1 });
    snaps.push(snap());
    series.push({ turn: t, sys: SYS, summary, notes: notesBlock, user: live.reduce((a, x) => a + x.user, 0), tool: live.reduce((a, x) => a + x.tool, 0), reply: live.reduce((a, x) => a + x.reply, 0), compacted });
  }
  const totalUnits = events.reduce((a, e) => a + e.units, 0), u = 12 / totalUnits;
  let acc = 0;
  events.forEach((e, i) => { e.start = +(0.4 + acc * u).toFixed(3); e.dur = +(e.units * u).toFixed(3); e.snap = i; acc += e.units; });
  const fin = status();
  const facts = FACTS.map((f, i) => Object.assign({}, f, { status: fin[i] }));
  const count = k => fin.filter(x => x === k).length;
  const factCounts = { verbatim: count('verbatim') + count('notes'), notes: count('notes'), gist: count('gist'), lost: count('lost'), unsaid: count('unsaid') };
  const said = FACTS.length - factCounts.unsaid, k = (n, w) => n + ' ' + w + (n === 1 ? '' : 's');
  const summaryText = k(N, 'turn') + ', ' + (compactions.length ? k(compactions.length, 'compaction') : 'no compaction') + ': ' +
    (notes ? 'all ' + said + ' facts kept exact in plan.md' : factCounts.verbatim + ' of ' + said + ' facts kept word for word, ' + factCounts.gist + ' only as a gist, ' + factCounts.lost + ' lost') + '.';
  const last = records[records.length - 1];
  const markers = events.filter(e => e.type === 'compact').map(e => e.start).concat([12.4]);
  return {
    limit: LIMIT, threshold: THRESH, sysTokens: SYS, keepRecent: KEEP, summaryFraction: FRAC, turnsN: N, large, notesOn: notes,
    turns: ALL.slice(0, N).map(d => ({ turn: d.turn, user: d.user, tool: d.tool, reply: d.reply, total: d.user + d.tool + d.reply, fact: factAt(d.turn) })),
    compactions, records, snaps, series, events, facts, factCounts,
    notesFile: notes ? facts.filter(f => f.turn <= N).map(f => ({ id: f.id, turn: f.turn, text: f.text })) : null,
    finalUsed: last.after, peakUsed: Math.max(...records.map(r => Math.max(r.before, r.after))),
    duration: 13, markers, summary: summaryText
  };
}

