function check(p) {
  const m = model(p), R = m.records, C = m.compactions;
  // 1. The desk never overflows: usage stays at or below the limit after every turn.
  const peakOk = m.peakUsed <= m.limit && R.every(r => r.after <= m.limit);
  // 2. Compaction happens exactly when adding the next turn would cross the threshold, and only then.
  const timingOk = R.every(r => r.compacted === (r.before + r.size > m.threshold)) && C.length === R.filter(r => r.compacted).length;
  // 3. Token accounting adds up after each compaction.
  const turnTok = t => m.turns[t - 1].total;
  const acctOk = C.every(c => {
    let folded = 0; for (let t = c.foldedFrom; t <= c.foldedTo; t++) folded += turnTok(t);
    const kept = c.kept.reduce((a, t) => a + turnTok(t), 0);
    return folded === c.foldedTurns && c.summary === Math.round(m.summaryFraction * (c.foldedTurns + c.oldSummary)) &&
      c.after === c.before - c.foldedTurns - c.oldSummary - c.oldNotes + c.summary + c.notesBlock &&
      c.after === m.sysTokens + c.summary + c.notesBlock + kept && c.after + turnTok(c.turn) <= m.threshold;
  });
  // 4. With notes on, no fact that was mentioned is lost or reduced to a gist.
  const said = m.facts.filter(f => f.status !== 'unsaid');
  const notesOk = !m.notesOn || said.every(f => f.status === 'notes');
  const c0 = C[0];
  return {
    pass: peakOk && timingOk && acctOk && notesOk,
    detail: (c0 ? C.length + ' compaction' + (C.length > 1 ? 's' : '') + ', the first at turn ' + c0.turn + ' (' + Math.round(c0.before / 1000) + 'k + ' + Math.round(turnTok(c0.turn) / 1000) + 'k would cross the ' + Math.round(m.threshold / 1000) + 'k threshold): ' + Math.round((c0.foldedTurns + c0.oldSummary) / 1000) + 'k folded into a summary of ' + Math.round(c0.summary / 1000) + 'k, leaving ' + Math.round(c0.after / 1000) + 'k'
      : 'No compaction needed: ' + m.turnsN + ' turns peak at ' + Math.round(m.peakUsed / 1000) + 'k, under the ' + Math.round(m.threshold / 1000) + 'k threshold') +
      '; peak ' + Math.round(m.peakUsed / 1000) + 'k of ' + m.limit / 1000 + 'k; ' +
      (m.notesOn ? 'notes on, all ' + said.length + ' mentioned facts kept exact in plan.md.' : 'notes off, ' + m.factCounts.lost + ' of ' + said.length + ' mentioned facts lost.')
  };
}
